const CALENDAR_ID    = 'primary';
const SHEET_ID       = '1N-qE4v81o0uxyXxLFeCamHSkvALFQIixrES3K6-hE6c';
const PUBLIC_BASE    = 'https://condone-making-amount.ngrok-free.dev';
const CLINIC_NAME    = 'Smile Dental Clinic';
const CLINIC_ADDRESS = '12 Main Boulevard, Lahore';
const CLINIC_PHONE   = '+92 300 000 0000';
const TIMEZONE       = 'Asia/Karachi';
const BOOKING_URL    = 'http://localhost:3000';   // where patients BOOK (not n8n)
const CLINIC_WHATSAPP = '15551915007';   // the clinic's WhatsApp number, digits only with country code, e.g. 923001234567.
                               // Email buttons open this chat with the message ready. '' = buttons work as before.
const CANCEL_CUTOFF_HOURS = 4;                    // no self-service cancel inside this window
/* ========================================================================== */

// --- shared helpers -------------------------------------------------------
const toMin  = t => { const [h,m] = String(t).split(':').map(Number); return h*60 + (m||0); };
const toHHMM = m => `${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`;
const parts  = (isoStr, tz) => {
  const f = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year:'numeric', month:'2-digit',
    day:'2-digit', hour:'2-digit', minute:'2-digit', hour12:false });
  const p = Object.fromEntries(f.formatToParts(new Date(isoStr)).map(x => [x.type, x.value]));
  return { date: `${p.year}-${p.month}-${p.day}`, min: (Number(p.hour) % 24) * 60 + Number(p.minute) };
};
const prettyDate = (d, tz) => new Date(d + 'T12:00:00Z')
  .toLocaleDateString('en-GB', { timeZone: tz, weekday:'long', day:'numeric', month:'long', year:'numeric' });
const pretty12 = t => { const [h,m] = String(t).split(':').map(Number);
  return `${((h+11)%12)+1}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`; };
const busyBlocks = (fb, calId, day, tz) => {
  const cal = fb.calendars || {};
  const raw = (cal[calId] && cal[calId].busy) || (Object.values(cal)[0] || {}).busy || [];
  const out = [];
  for (const b of raw) {
    const s = parts(b.start, tz), e = parts(b.end, tz);
    if (e.date < day || s.date > day) continue;
    out.push([ s.date < day ? 0 : s.min, e.date > day ? 1440 : e.min ]);
  }
  return out;
};
// --------------------------------------------------------------------------

const rows = ($input.first().json.values) || [];
const now  = Date.now();
const out  = [];
rows.forEach((r, i) => {
  if (String(r[2] || '').toUpperCase() !== 'PENDING') return;
  const exp = Date.parse(r[14] || '');
  if (!exp || exp > now) return;
  out.push({ json: { CALENDAR_ID, SHEET_ID, PUBLIC_BASE, BOOKING_URL, CLINIC_WHATSAPP, CLINIC_NAME, TIMEZONE,
    rowNumber: i + 2, ref: r[0], eventId: r[12], calendarId: String(r[20] || '').trim() || CALENDAR_ID, name: r[8], email: r[10],
    serviceName: r[4], date: r[5], time: r[6],
    prettyDate: prettyDate(r[5], TIMEZONE), prettyTime: pretty12(r[6]) } });
});
console.log('Releasing ' + out.length + ' expired hold(s)');
return out;

const v = $('Find Expired Holds').item.json;
// Buttons open the clinic's WhatsApp chat with the message already typed; the patient just presses send.
const waDigits = String(v.CLINIC_WHATSAPP || '').replace(/\D/g, '');
const wa = text => waDigits.length >= 8 ? `https://wa.me/${waDigits}?text=${encodeURIComponent(text)}` : '';
const waBook = wa('I would like to book an appointment.');
const html = `
<div style="font-family:Helvetica,Arial,sans-serif;max-width:520px;margin:0 auto;color:#123F52">
  <div style="background:#B45309;color:#fff;padding:20px 24px;border-radius:14px 14px 0 0;font-size:18px;font-weight:bold">
    Your slot hold has expired</div>
  <div style="border:1px solid #CDE9F1;border-top:0;border-radius:0 0 14px 14px;padding:24px;background:#fff">
    <p>Hello ${v.name},</p>
    <p>We held <strong>${v.prettyDate} at ${v.prettyTime}</strong> for you, but the confirmation
       link was not used in time, so the slot has been released for other patients.</p>
    <p>No problem &mdash; you can book again in under a minute.</p>
    <a href="${waBook || v.BOOKING_URL}" style="display:block;text-align:center;background:#0E7490;color:#fff;
       text-decoration:none;padding:14px;border-radius:12px;font-weight:bold">${waBook ? 'Book again on WhatsApp' : 'Book again'}</a>
  </div></div>`;
return [{ json: { ...v, html, subject: `Your held slot has been released  [Ref: ${v.ref}]` } }];
